# 🔰API Routes

🔴Variáveis dinâmicas acessáveis pelo req.

```javascript
//.../pages/api/comments/[id].js
import comments from '../comments.json'

export default (req, res) => {
  res.status(200).json({
    post: req.query.id,
    comments
  })
}
```

‌

#### 🟡**Exemplo de arquivo com if/else:**

```javascript
// pages/api/items.js

let items = []; // Simulação de um banco de dados em memória

export default (req, res) => {
  if (req.method === 'GET') {
    res.status(200).json(items);
  } else if (req.method === 'POST') {
    const newItem = req.body;
    if (!newItem.id || !newItem.name) {
      res.status(400).json({ message: 'ID e nome são obrigatórios' });
    } else {
      items.push(newItem);
      res.status(201).json(newItem);
    }
  } else if (req.method === 'PUT') {
    const updatedItem = req.body;
    if (!updatedItem.id || !updatedItem.name) {
      res.status(400).json({ message: 'ID e nome são obrigatórios' });
    } else {
      const itemIndex = items.findIndex((item) => item.id === updatedItem.id);
      if (itemIndex === -1) {
        res.status(404).json({ message: 'Item não encontrado' });
      } else {
        items[itemIndex] = updatedItem;
        res.status(200).json(updatedItem);
      }
    }
  } else if (req.method === 'DELETE') {
    const itemId = req.query.id;
    if (!itemId) {
      res.status(400).json({ message: 'ID é obrigatório' });
    } else {
      items = items.filter((item) => item.id !== itemId);
      res.status(204).end();
    }
  } else {
    res.status(405).end(); // Method Not Allowed
  }
};
```

